import numpy as np


def lbp_code(patch):
    centre = patch[1, 1]
    order = [(0, 0), (0, 1), (0, 2), (1, 2), (2, 2), (2, 1), (2, 0), (1, 0)]
    code = 0
    for i, (y, x) in enumerate(order):
        if patch[y, x] >= centre:
            code += 2 ** i
    return code
